import type {
  CanonicalizationOrTransformationAlgorithm,
  CanonicalizationOrTransformationAlgorithmProcessOptions,
  NamespacePrefix,
  RenderedNamespace,
} from "./types";
import * as utils from "./utils";
import * as isDomNode from "@xmldom/is-dom-node";

type C14nOptionsWithXmlAttributes = CanonicalizationOrTransformationAlgorithmProcessOptions & {
  ancestorXmlAttributes?: utils.InheritedXmlAttribute[];
};

export class C14nCanonicalization implements CanonicalizationOrTransformationAlgorithm {
  protected includeComments = false;

  constructor() {
    this.includeComments = false;
  }

  attrCompare(a, b) {
    if (!a.namespaceURI && b.namespaceURI) {
      return -1;
    }
    if (!b.namespaceURI && a.namespaceURI) {
      return 1;
    }

    const left = a.namespaceURI + a.localName;
    const right = b.namespaceURI + b.localName;

    if (left === right) {
      return 0;
    } else if (left < right) {
      return -1;
    } else {
      return 1;
    }
  }

  nsCompare(a, b) {
    const attr1 = a.prefix;
    const attr2 = b.prefix;
    if (attr1 === attr2) {
      return 0;
    }
    return attr1.localeCompare(attr2);
  }

  renderAttrs(node) {
    let i;
    let attr;
    const attrListToRender: Attr[] = [];

    if (isDomNode.isCommentNode(node)) {
      return this.renderComment(node);
    }

    if (node.attributes) {
      for (i = 0; i < node.attributes.length; ++i) {
        attr = node.attributes[i];
        if (attr.name === "xmlns" || attr.prefix === "xmlns") {
          continue;
        }
        attrListToRender.push(attr);
      }
    }

    attrListToRender.sort(this.attrCompare);

    const res = attrListToRender.map((attr) => {
      return ` ${attr.name}="${utils.encodeSpecialCharactersInAttribute(attr.value)}"`;
    });

    return res.join("");
  }

  /**
   * Create the string of all namespace declarations that should appear on this element
   *
   * @param node The node we now render
   * @param prefixesInScope The prefixes defined on this node parents which are a part of the output set
   * @param defaultNs The current default namespace
   * @param defaultNsForPrefix
   * @param ancestorNamespaces Import ancestor namespaces if it is specified
   * @param namespacesInScope The namespaces bound on this node's output ancestors, nearest last.
   *   Without it, a prefix in `prefixesInScope` counts as in scope whatever it is bound to.
   * @api private
   */
  renderNs(
    node: Element,
    prefixesInScope: string[],
    defaultNs: string,
    defaultNsForPrefix: string,
    ancestorNamespaces: NamespacePrefix[],
    namespacesInScope?: NamespacePrefix[],
  ): RenderedNamespace {
    let i;
    let attr;
    const res: string[] = [];
    let newDefaultNs = defaultNs;
    const nsListToRender: { prefix: string; namespaceURI: string }[] = [];
    const currNs = node.namespaceURI || "";

    const isInScope = (prefix: string, namespaceURI: string) =>
      namespacesInScope
        ? utils.isPrefixInScope(namespacesInScope, prefix, namespaceURI)
        : prefixesInScope.indexOf(prefix) !== -1;
    const renderDeclaration = (prefix: string, namespaceURI: string) => {
      nsListToRender.push({ prefix, namespaceURI });
      prefixesInScope.push(prefix);
      namespacesInScope?.push({ prefix, namespaceURI });
    };

    if (node.prefix) {
      const namespaceURI = node.namespaceURI || defaultNsForPrefix[node.prefix];
      if (!isInScope(node.prefix, namespaceURI)) {
        renderDeclaration(node.prefix, namespaceURI);
      }
    }

    // The default namespace is independent of a prefixed element's namespaceURI.
    // https://www.w3.org/TR/2001/REC-xml-c14n-20010315#ProcessingModel
    let localDefaultNs: string | null = null;
    if (node.attributes) {
      for (i = 0; i < node.attributes.length; ++i) {
        if (node.attributes[i].name === "xmlns") {
          localDefaultNs = node.attributes[i].value;
        }
      }
    }

    let nodeDefaultNs: string;
    if (localDefaultNs !== null) {
      nodeDefaultNs = localDefaultNs;
    } else if (node.prefix) {
      nodeDefaultNs = defaultNs;
    } else {
      nodeDefaultNs = currNs;
    }

    if (nodeDefaultNs !== defaultNs) {
      newDefaultNs = nodeDefaultNs;
      res.push(' xmlns="', utils.encodeSpecialCharactersInAttribute(newDefaultNs), '"');
    }

    //handle the attributes namespace
    if (node.attributes) {
      for (i = 0; i < node.attributes.length; ++i) {
        attr = node.attributes[i];

        if (attr.prefix === "xmlns" && !isInScope(attr.localName, attr.value)) {
          renderDeclaration(attr.localName, attr.value);
        }

        if (
          attr.prefix &&
          !isInScope(attr.prefix, attr.namespaceURI) &&
          attr.prefix !== "xmlns" &&
          attr.prefix !== "xml"
        ) {
          renderDeclaration(attr.prefix, attr.namespaceURI);
        }
      }
    }

    if (utils.isArrayHasLength(ancestorNamespaces)) {
      // The apex's own declaration shadows an ancestor's binding of the same prefix, default
      // included. https://www.w3.org/TR/REC-xml-names/#scoping
      for (const ancestorNamespace of ancestorNamespaces) {
        const isShadowed =
          nsListToRender.some((ns) => ns.prefix === ancestorNamespace.prefix) ||
          (!ancestorNamespace.prefix && localDefaultNs !== null);

        if (!isShadowed) {
          nsListToRender.push(ancestorNamespace);
          if (!ancestorNamespace.prefix) {
            newDefaultNs = ancestorNamespace.namespaceURI;
          }
        }
      }
    }

    nsListToRender.sort(this.nsCompare);

    //render namespaces
    res.push(
      ...nsListToRender.map((attr) => {
        const namespaceURI = utils.encodeSpecialCharactersInAttribute(attr.namespaceURI);
        if (attr.prefix) {
          return ` xmlns:${attr.prefix}="${namespaceURI}"`;
        }
        return ` xmlns="${namespaceURI}"`;
      }),
    );

    return { rendered: res.join(""), newDefaultNs };
  }

  /**
   * @param node Node
   */
  processInner(
    node,
    prefixesInScope,
    defaultNs,
    defaultNsForPrefix,
    ancestorNamespaces,
    namespacesInScope?: NamespacePrefix[],
  ) {
    if (isDomNode.isDocumentNode(node)) {
      const res: string[] = [];
      for (let i = 0; i < node.childNodes.length; i++) {
        const child = node.childNodes[i];
        if (isDomNode.isCommentNode(child)) {
          if (this.includeComments) {
            res.push(this.renderComment(child, true));
          }
          continue;
        }
        if (utils.isCanonicalDocumentChild(child)) {
          res.push(
            this.processInner(
              child,
              prefixesInScope,
              defaultNs,
              defaultNsForPrefix,
              ancestorNamespaces,
              namespacesInScope,
            ),
          );
        }
      }
      return res.join("\n");
    }
    if (isDomNode.isCommentNode(node)) {
      return this.renderComment(node);
    }
    if (isDomNode.isProcessingInstructionNode(node)) {
      return utils.renderProcessingInstruction(node);
    }
    if (node.data) {
      return utils.encodeSpecialCharactersInText(node.data);
    }

    if (isDomNode.isElementNode(node)) {
      let i;
      let pfxCopy;
      const ns = this.renderNs(
        node,
        prefixesInScope,
        defaultNs,
        defaultNsForPrefix,
        ancestorNamespaces,
        namespacesInScope,
      );
      const res = ["<", node.tagName, ns.rendered, this.renderAttrs(node), ">"];

      for (i = 0; i < node.childNodes.length; ++i) {
        pfxCopy = prefixesInScope.slice(0);
        res.push(
          this.processInner(
            node.childNodes[i],
            pfxCopy,
            ns.newDefaultNs,
            defaultNsForPrefix,
            [],
            namespacesInScope?.slice(0),
          ),
        );
      }

      res.push("</", node.tagName, ">");
      return res.join("");
    }

    throw new Error(`Unable to canonicalize node type: ${node.nodeType}`);
  }

  // Thanks to deoxxa/xml-c14n for comment renderer
  renderComment(node: Comment, documentChild = false) {
    if (!this.includeComments) {
      return "";
    }

    const encodedText = utils.encodeSpecialCharactersInText(node.data);
    if (documentChild) {
      return `<!--${encodedText}-->`;
    }

    const isOutsideDocument = node.ownerDocument === node.parentNode;
    let isBeforeDocument = false;
    let isAfterDocument = false;

    if (isOutsideDocument) {
      let nextNode: ChildNode | null = node;
      let previousNode: ChildNode | null = node;

      while (nextNode !== null) {
        if (nextNode === node.ownerDocument.documentElement) {
          isBeforeDocument = true;
          break;
        }

        nextNode = nextNode.nextSibling;
      }

      while (previousNode !== null) {
        if (previousNode === node.ownerDocument.documentElement) {
          isAfterDocument = true;
          break;
        }

        previousNode = previousNode.previousSibling;
      }
    }

    const afterDocument = isAfterDocument ? "\n" : "";
    const beforeDocument = isBeforeDocument ? "\n" : "";
    return `${afterDocument}<!--${encodedText}-->${beforeDocument}`;
  }

  /**
   * Perform canonicalization of the given node
   *
   * @param node
   * @api public
   */
  process(node: Node, options: CanonicalizationOrTransformationAlgorithmProcessOptions): string {
    options = options || {};
    const defaultNs = options.defaultNs || "";
    const defaultNsForPrefix = options.defaultNsForPrefix || {};
    const ancestorNamespaces = options.ancestorNamespaces || [];
    const inheritedXmlAttributes =
      (options as C14nOptionsWithXmlAttributes).ancestorXmlAttributes ??
      utils.findAncestorXmlAttributes(node);
    let canonicalNode = node;
    if (isDomNode.isElementNode(node) && inheritedXmlAttributes.length > 0) {
      const clone = node.cloneNode(true);
      isDomNode.assertIsElementNode(clone);
      for (const attr of inheritedXmlAttributes) {
        if (!clone.hasAttributeNS("http://www.w3.org/XML/1998/namespace", attr.localName)) {
          clone.setAttributeNS(
            "http://www.w3.org/XML/1998/namespace",
            `xml:${attr.localName}`,
            attr.value,
          );
        }
      }
      canonicalNode = clone;
    }

    const prefixesInScope: string[] = [];
    for (let i = 0; i < ancestorNamespaces.length; i++) {
      prefixesInScope.push(ancestorNamespaces[i].prefix);
    }

    const res = this.processInner(
      canonicalNode,
      prefixesInScope,
      defaultNs,
      defaultNsForPrefix,
      ancestorNamespaces,
      ancestorNamespaces.slice(),
    );
    return res;
  }

  getAlgorithmName() {
    return "http://www.w3.org/TR/2001/REC-xml-c14n-20010315";
  }
}

/**
 * Add c14n#WithComments here (very simple subclass)
 */
export class C14nCanonicalizationWithComments extends C14nCanonicalization {
  constructor() {
    super();
    this.includeComments = true;
  }

  getAlgorithmName() {
    return "http://www.w3.org/TR/2001/REC-xml-c14n-20010315#WithComments";
  }
}
